<?php
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
final class GivingTuesdayHashtagMigration {
 const ID='031_update_givingtuesday_hashtag';
 public static function checksum(){return hash('sha256',file_get_contents(__FILE__).file_get_contents(get_theme_file_path('/inc/givingtuesday-hashtag.php')));}
 public static function plan(){preflight();$p=get_page_by_path('givingtuesday');$id=$p?(int)$p->ID:0;if(!$p||$p->post_type!=='page'||!current_user_can('edit_post',$id))fail('An editable Giving Tuesday page is required.');$after=ed_givingtuesday_add_hashtag($p->post_content);return ['key'=>'page.givingtuesday.hashtag','kind'=>'page','id'=>$id,'before'=>$p->post_content,'after'=>$after,'action'=>$p->post_content===$after?'already-satisfied':'update'];}
 public static function preview(){ $state=history()[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('031 checksum changed.');$p=['actor'=>get_current_user_id(),'checksum'=>self::checksum(),'operation'=>self::plan(),'created'=>time()];update_option('edm_givingtuesday_hashtag_preview',$p,false);return $p; }
 public static function run(){preflight();$token=lock_acquire();try{$h=history();$state=$h[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('031 checksum changed.');if(($state['status']??'')==='completed')return 'Giving Tuesday hashtag migration already completed; editorial changes preserved.';$p=get_option('edm_givingtuesday_hashtag_preview');if(!$p||$p['actor']!==get_current_user_id()||$p['checksum']!==self::checksum()||$p['created']<time()-DAY_IN_SECONDS)fail('Fresh Giving Tuesday hashtag preview required.');$op=self::plan();$expected=$state['operation']??$p['operation'];if($op['id']!==$expected['id']||$op['after']!==$expected['after']||($op['before']!==$expected['before']&&$op['action']!=='already-satisfied'))fail('Giving Tuesday changed after preview.');$h[self::ID]=array_merge($state,['status'=>'running','checksum'=>self::checksum(),'actor'=>get_current_user_id(),'run_id'=>$state['run_id']??wp_generate_uuid4(),'started'=>$state['started']??time(),'operation'=>$expected,'destination_id'=>$op['id']]);lock_check($token);save_history($h);apply_operation($op);lock_check($token);if(get_post_field('post_content',$op['id'])!==$expected['after'])fail('Giving Tuesday hashtag update verification failed.');$h[self::ID]['status']='completed';$h[self::ID]['completed']=time();save_history($h);return 'Giving Tuesday hashtag updated; other page content preserved.';}finally{lock_release($token);}}
}
foreach(['preview','run'] as $mode)add_action('admin_post_edm_givingtuesday_hashtag_'.$mode,function()use($mode){if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('edm_givingtuesday_hashtag_'.$mode);try{if($mode==='run'&&empty($_POST['backup']))fail('Backup acknowledgment required.');$result=$mode==='preview'?GivingTuesdayHashtagMigration::preview():GivingTuesdayHashtagMigration::run();update_option('edm_givingtuesday_hashtag_notice',is_string($result)?$result:'Preview ready.',false);}catch(\Throwable $e){update_option('edm_givingtuesday_hashtag_notice',$e->getMessage(),false);}wp_safe_redirect(admin_url('tools.php?page=eyedonation-migrations#edm-givingtuesday-hashtag'));exit;});
add_action('admin_footer',function(){if(($_GET['page']??'')!=='eyedonation-migrations'||!current_user_can('manage_options'))return;echo '<div class="wrap" id="edm-givingtuesday-hashtag"><h2>031 — Giving Tuesday hashtag layout</h2><p>Adds the editable light green campaign hashtag beneath the thank-you text. Status: '.esc_html(history()[GivingTuesdayHashtagMigration::ID]['status']??'pending').'</p><p role="status">'.esc_html(get_option('edm_givingtuesday_hashtag_notice','')).'</p>';foreach(['preview'=>'Preview Giving Tuesday hashtag','run'=>'Apply / Resume Giving Tuesday hashtag'] as $mode=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="edm_givingtuesday_hashtag_'.$mode.'">';wp_nonce_field('edm_givingtuesday_hashtag_'.$mode);if($mode==='run')echo '<p><label><input type="checkbox" name="backup" value="1" required> I have a recoverable backup.</label></p>';submit_button($label);echo '</form>';}$p=get_option('edm_givingtuesday_hashtag_preview');if($p)echo '<details><summary>Current / proposed content</summary><pre>'.esc_html(wp_json_encode($p['operation'],JSON_PRETTY_PRINT)).'</pre></details>';echo '</div>';});
